mapper.select:
/** slave-secedeuser-mapper.getSecedeUserListByParam (회원탈퇴관리 목록 조회) */ SELECT A.USER_ID, crypto_dec('normal', A.LOGIN_ID, '', 0) AS LOGIN_ID, DATE_FORMAT(A.LEAVE_DATE,'%Y-%m-%d') AS LEAVE_DATE, A.LEAVE_REASON, A.LEAVE_CODE, A.LEAVE_USER_ID, A.LEAVE_CODE_LABEL, crypto_dec('normal', A.LEAVE_USER_NAME, '', 0) AS LEAVE_USER_NAME, (SELECT R.ROLE_NAME FROM OP_USER_ROLE UR INNER JOIN OP_ROLE R ON R.AUTHORITY = UR.AUTHORITY WHERE UR.USER_ID = A.LEAVE_USER_ID AND UR.AUTHORITY LIKE 'ROLE_ADMIN_%' LIMIT 1) AS ROLE_NAME FROM (
SELECT U.USER_ID, U.LOGIN_ID, U.LEAVE_DATE, UD.LEAVE_REASON, UD.LEAVE_CODE, UD.LEAVE_USER_ID, C.LABEL AS LEAVE_CODE_LABEL, IFNULL(M.USER_NAME, IFNULL(U2.USER_NAME, '')) AS LEAVE_USER_NAME FROM OP_USER U INNER JOIN OP_USER_DETAIL UD ON UD.USER_ID = U.USER_ID AND UD.USE_FLAG = 'N' LEFT OUTER JOIN OP_COMMON_CODE C ON C.CODE_TYPE = 'LEAVE_CODE' AND C.LANGUAGE = 'ko' AND C.USE_YN = 'Y' AND C.ID = UD.LEAVE_CODE LEFT OUTER JOIN OP_MANAGER M ON M.USER_ID = UD.LEAVE_USER_ID LEFT OUTER JOIN OP_USER U2 ON U2.USER_ID = UD.LEAVE_USER_ID
ORDER BY U.LEAVE_DATE DESC
) A
